"""Read-only candidate audit; never print matching secret values."""
import json
import re
import subprocess
from pathlib import Path

root = Path(__file__).resolve().parents[3]
changed = subprocess.check_output(['git', 'diff', '--name-only', 'HEAD', '-z'], cwd=root).split(b'\0')
untracked = subprocess.check_output(['git', 'ls-files', '--others', '--exclude-standard', '-z'], cwd=root).split(b'\0')
files = sorted({p.decode() for p in changed + untracked if p})
secrets = set()
for relative in ['.env', '.local/tests/environment', '.local/checks/environment']:
    path = root / relative
    if path.exists():
        for line in path.read_text().splitlines():
            if '=' not in line or line.lstrip().startswith('#'):
                continue
            key, value = line.split('=', 1)
            value = value.strip().strip('\"\'')
            if re.search('PASSWORD|SECRET|TOKEN|ACCESS_KEY', key, re.I) and len(value) >= 12:
                secrets.add(value.encode())

def collect(value):
    if isinstance(value, dict):
        for key, item in value.items():
            if re.search('password|secretkey|accesskey', key, re.I) and isinstance(item, str) and len(item) >= 12:
                secrets.add(item.encode())
            else:
                collect(item)
    elif isinstance(value, list):
        for item in value:
            collect(item)

for relative in ['.local/seaweedfs/s3.json', '.local/tests/s3.json']:
    path = root / relative
    if path.exists():
        collect(json.loads(path.read_text()))
pattern = rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|\b(?:AKIA|ASIA)[A-Z0-9]{16}\b|\b(?:gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{40,}|sk-(?:proj-)?[A-Za-z0-9_-]{30,})\b|(?i:\b(?:postgres(?:ql)?|https?|s3)://[^\s/:]+:[^\s/@]+@)'
issues = []
for name in files:
    path = root / name
    data = path.read_bytes()
    if path.suffix not in {'.md', '.html', '.tsx', '.css', '.sh', '.py', '.cjs'}:
        issues.append((name, 'unexpected artifact type'))
    if b'\0' in data:
        issues.append((name, 'binary/media data'))
    data.decode('utf8')
    if re.search(pattern, data) or any(secret in data for secret in secrets):
        issues.append((name, 'potential credential'))
    if re.search(rb'"type"\s*:\s*"(?:session_meta|response_item|event_msg)"', data):
        issues.append((name, 'possible AI journal'))
print(f'Scanned {len(files)} Git candidates (modified + untracked), all UTF-8 text.')
for name, label in issues:
    print(f'{name}: {label}')
if issues:
    raise SystemExit(1)
print('PASS: no active local credentials, key/token/credential-URL patterns, AI journals, media, binaries or unexpected temporary file types.')
print('All review logs, screenshots, synthetic clip, helpers and HEAD snapshots are inside ignored .local/.')

